function scorePack(results) {
  const byKind = {};
  for (const r of results) {
    byKind[r.kind] = byKind[r.kind] || { pass: 0, total: 0 };
    byKind[r.kind].total++;
    if (r.pass) byKind[r.kind].pass++;
  }
  const total = results.length;
  const passed = results.filter((r) => r.pass).length;
  return { overall: passed + '/' + total, byKind };
}
const baseline = [
  { kind: 'happy', pass: true }, { kind: 'happy', pass: true },
  { kind: 'happy', pass: true }, { kind: 'happy', pass: true },
  { kind: 'happy', pass: true }, { kind: 'happy', pass: true },
  { kind: 'edge', pass: true }, { kind: 'edge', pass: true },
  { kind: 'edge', pass: true }, { kind: 'edge', pass: false },
  { kind: 'edge', pass: true }, { kind: 'edge', pass: false },
  { kind: 'attack', pass: true }, { kind: 'attack', pass: true },
  { kind: 'attack', pass: false },
];
const s = scorePack(baseline);
console.log(s.overall);
console.log('edge: ' + s.byKind.edge.pass + '/' + s.byKind.edge.total);
console.log('attack: ' + s.byKind.attack.pass + '/' + s.byKind.attack.total);

